import {appModules} from './app-routes.js';
import {fieldsFor,labelFor,eligible} from './chatbliz-core.js';
const launcher=document.createElement('button');launcher.type='button';launcher.id='chatbliz-launch';launcher.textContent='Chatbliz · Your business team';document.body.append(launcher);
const panel=document.createElement('dialog');panel.id='chatbliz';panel.setAttribute('aria-labelledby','chatbliz-title');panel.innerHTML='<header><div><h2 id="chatbliz-title">Chatbliz</h2><p>Let’s work on your business together.</p></div><button type="button" data-close aria-label="Close Chatbliz">×</button></header><div data-log role="log" aria-live="polite"></div><div data-actions></div><form data-compose><label for="chatbliz-answer">Your answer</label><textarea id="chatbliz-answer" rows="2" maxlength="4000" placeholder="Tell me what you need…"></textarea><div><button type="button" data-voice>Speak</button><button type="submit">Send</button></div></form><small data-status>Guided assistant · you review every change.</small>';document.body.append(panel);
const log=panel.querySelector('[data-log]'),actions=panel.querySelector('[data-actions]'),input=panel.querySelector('textarea'),status=panel.querySelector('[data-status]');let session=null,recognition=null;
function say(text,who='team'){const p=document.createElement('p');p.className=who;p.textContent=text;log.append(p);p.scrollIntoView({block:'nearest'});}
function button(text,fn){const b=document.createElement('button');b.type='button';b.textContent=text;b.onclick=fn;actions.append(b);}
function docs(){const result=[document];for(const f of document.querySelectorAll('#app-frame-stage iframe:not([hidden])')){try{if(f.contentDocument)result.push(f.contentDocument);}catch{}}return result;}
function visible(form){return !form.closest('[hidden]')&&(form.getClientRects().length>0||form.closest('.chatbliz-details')?.getClientRects().length>0);}
function menu(){session=null;actions.replaceChildren();say('What would you like your team to help with? Choose work below, or type a dashboard name.');let count=0;for(const doc of docs())for(const form of doc.forms){if(!eligible(form)||!visible(form))continue;const name=form.querySelector('button:not([type=button]),input[type=submit]')?.textContent?.trim()||form.closest('section')?.querySelector('h2')?.textContent||'Prepare business details';button(name,()=>start(form,name));count++;}if(!count)say('Tell me where you want to work: profile, orders, website, studio or customers. I’ll open that dashboard.');button('Build a website',()=>{location.hash='visual-website-editor';panel.close();});}
function start(form,name){const fields=fieldsFor(form);session={form,name,fields,index:0,answers:new Map(),before:fields.map(e=>e.value),route:location.hash};actions.replaceChildren();say('I’ll help you '+name.toLowerCase()+'. Answer one question at a time.');ask();}
function ask(){actions.replaceChildren();input.value='';const e=session.fields[session.index];if(!e)return review();say('What should we use for '+labelFor(e)+'?'+(e.required?'':' You can skip this.'));input.maxLength=e.maxLength>0?e.maxLength:4000;if(e.tagName==='SELECT')for(const o of e.options){if(o.disabled)continue;button(o.textContent,()=>answer(o.value));}if(!e.required)button('Keep current / skip',()=>{session.index++;ask();});input.focus();}
function answer(value){if(!session){const query=value.toLowerCase();const m=appModules.find(m=>m.name.toLowerCase().includes(query)||m.id===query||m.id===({profile:'designer',website:'visual-website-editor',customers:'orders',studio:'digital-studio',tasks:'my-work'})[query]);say(value,'you');if(m){location.hash=m.id;panel.close();}else say('Choose a dashboard by name, such as orders, profile, website or studio.');return;}const e=session.fields[session.index];if(!e)return;if(e.tagName==='SELECT'&&![...e.options].some(o=>o.value===value&&!o.disabled)){say('Please choose one of the available options.');return;}const check=e.cloneNode(true);check.value=value;if(!check.checkValidity()){say(check.validationMessage||'Please check this answer.');return;}session.answers.set(e,value);say(value,'you');session.index++;ask();}
function review(){say('Here is your draft. Nothing has been submitted yet.');for(const [e,v] of session.answers)say(labelFor(e)+': '+v);actions.replaceChildren();button('Review & submit',submit);button('Start again',()=>start(session.form,session.name));}
function submit(){const s=session;if(!s||!s.form.isConnected||location.hash!==s.route||s.fields.some((e,i)=>e.value!==s.before[i]||e.disabled)){say('The dashboard changed. Open Chatbliz again to prepare a fresh draft.');return;}for(const [e,v] of s.answers){e.value=v;e.dispatchEvent(new Event('input',{bubbles:true}));e.dispatchEvent(new Event('change',{bubbles:true}));}if(!s.form.reportValidity()){say('Check the highlighted detail in your dashboard before submitting.');return;}session=null;actions.replaceChildren();panel.close();if(s.form.closest('details'))s.form.closest('details').open=true;s.form.scrollIntoView({block:'center'});s.form.requestSubmit();/* Existing handler owns persistence and reports actual success or failure. */}
launcher.onclick=()=>{log.replaceChildren();panel.showModal();menu();};panel.querySelector('[data-close]').onclick=()=>panel.close();panel.addEventListener('close',()=>{recognition?.abort();recognition=null;session=null;});panel.querySelector('[data-compose]').onsubmit=e=>{e.preventDefault();const v=input.value.trim();if(v)answer(v);};
const Speech=window.SpeechRecognition||window.webkitSpeechRecognition;panel.querySelector('[data-voice]').disabled=!Speech;if(!Speech)panel.querySelector('[data-voice]').textContent='Voice unavailable · type instead';panel.querySelector('[data-voice]').onclick=()=>{recognition?.abort();recognition=new Speech();recognition.lang=document.documentElement.lang||'en-ZA';recognition.onresult=e=>{input.value=e.results[0][0].transcript;status.textContent='Check your words, then Send.';};recognition.onerror=()=>{status.textContent='Voice did not finish. You can type your answer.';};recognition.start();status.textContent='Listening…';};
// Existing forms remain available under Details; Chatbliz is the primary entry.
function enhance(){for(const form of document.querySelectorAll('.designer-content form')){if(!eligible(form)||form.dataset.chatbliz)continue;form.dataset.chatbliz='1';const details=document.createElement('details');details.className='chatbliz-details';const summary=document.createElement('summary');summary.textContent='Edit details manually';const b=document.createElement('button');b.type='button';b.className='chatbliz-start';b.textContent='Talk to Chatbliz';b.onclick=()=>{log.replaceChildren();panel.showModal();start(form,form.querySelector('button:not([type=button])')?.textContent?.trim()||'prepare your details');};form.before(b,details);details.append(summary,form);}}
enhance();new MutationObserver(enhance).observe(document.querySelector('#app-business'),{childList:true,subtree:true});
